const tokens=[{id:"copper",name:"Copper Token",material:"Copper",color:"#b87333",description:"A reconstructed representation of the lower-cost token currency meant to replace silver."},{id:"brass",name:"Brass Token",material:"Brass",color:"#b5a642",description:"A reconstructed representation used for the educational simulation."}],tughlaqTimeline=[{id:"context",title:"Economic Context",description:"The experiment emerged during Muhammad bin Tughlaq's reign as part of wider monetary and administrative policies, aiming to circumvent a shortage of precious metals.",type:"documented"},{id:"introduction",title:"Token Currency",description:"A token currency experiment attempted to introduce less expensive metal currency (copper and brass) into circulation with the intended value of silver tankas.",type:"documented"},{id:"circulation",title:"Circulation",description:"The tokens were intended to function as money within the monetary system, accepted for taxes and market transactions.",type:"documented"},{id:"counterfeiting",title:"Counterfeiting",description:"Counterfeiting severely undermined confidence. Because the minting was relatively simple and lacked a state monopoly on complex striking techniques, every house effectively became a mint.",type:"documented"},{id:"withdrawal",title:"Withdrawal",description:"The experiment was eventually withdrawn. The Sultan had to exchange the counterfeit and genuine tokens with actual gold and silver from the royal treasury, causing immense financial loss.",type:"documented"}],sources=[{title:"Encyclopaedia Britannica",description:"Background reference for Muhammad bin Tughlaq and his monetary reforms."},{title:"Reserve Bank of India Museum",description:"Historical context regarding Indian currency and medieval numismatics."},{title:"Barani's Tarikh-i-Firoz Shahi",description:"Contemporary historical account documenting the economic impacts of the Sultan's reign."}],steps=["Token","Value","Circulation","Challenge","Outcome"];let currentStage="select",selectedToken=null;function renderTokens(){const e=document.getElementById("tokens-container");e&&(e.innerHTML=tokens.map(e=>`\n    <article class="card">\n      <div class="token-circle" style="background: ${e.color};">\n        TOKEN\n      </div>\n      <h3>${e.name}</h3>\n      <p>${e.description}</p>\n      <span class="label" style="margin-top: 15px;">Educational reconstruction</span>\n    </article>\n  `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&(e.innerHTML=tughlaqTimeline.map(e=>`\n    <div class="timeline-event">\n      <span class="label">Documented history</span>\n      <h3>${e.title}</h3>\n      <p class="section-text">${e.description}</p>\n    </div>\n  `).join(""))}function renderSources(){const e=document.getElementById("sources-container");e&&(e.innerHTML=sources.map(e=>`\n    <div class="source-card">\n      <div class="source-title">${e.title}</div>\n      <p style="color: var(--text-muted); font-size: 0.9rem; margin-top: 5px;">${e.description}</p>\n    </div>\n  `).join(""))}function setStage(e){currentStage=e,renderSimulation()}function selectTokenAction(e){selectedToken=tokens.find(n=>n.id===e),setStage("value")}function renderSimulation(){const e=document.getElementById("simulation-root"),n=document.getElementById("sim-progress");if(!e||!n)return;const t={select:0,value:1,circulation:2,counterfeit:3,withdrawal:4,complete:5}[currentStage];n.innerHTML=steps.map((e,n)=>`\n    <div class="progress-step ${n<=t?"active":""}">\n      <span class="step-num">${n+1}</span>\n      <span>${e}</span>\n    </div>\n  `).join("");let i="";"select"===currentStage?i=`\n      <div>\n        <h3 style="font-size: 1.5rem; margin-bottom: 20px;">1. Select a token</h3>\n        <div class="grid-2">\n          ${tokens.map(e=>`\n            <button class="sim-btn" onclick="selectTokenAction('${e.id}')">\n              <span style="font-size: 1.2rem; font-weight: bold; display: block;">${e.name}</span>\n              <span style="font-size: 0.9rem; color: var(--text-muted); margin-top: 5px; display: block;">Select token to begin</span>\n            </button>\n          `).join("")}\n        </div>\n      </div>\n    `:"value"===currentStage?i=`\n      <div class="sim-box">\n        <span class="label">Step 2</span>\n        <h3 style="font-size: 2rem; margin: 10px 0;">Intended Value</h3>\n        <p style="font-size: 1.1rem; color: var(--text-muted); line-height: 1.6;">\n          You selected the ${selectedToken.name}. The experiment attempted to give this token currency a value equal to a silver tanka, far beyond the intrinsic value of its ${selectedToken.material.toLowerCase()}.\n        </p>\n        <button class="action-btn" onclick="setStage('circulation')">Put Token Into Circulation &rarr;</button>\n      </div>\n    `:"circulation"===currentStage?i=`\n      <div class="sim-box">\n        <span class="label">Step 3</span>\n        <h3 style="font-size: 2rem; margin: 10px 0;">Circulation</h3>\n        <div style="display: flex; justify-content: center; align-items: center; gap: 20px; margin: 30px 0;">\n          <div class="token-circle" style="background: ${selectedToken.color}; width: 80px; height: 80px; margin: 0; font-size: 0.8rem;">TOKEN</div>\n          <i class="fa-solid fa-arrow-right" style="font-size: 2rem; color: var(--text-muted);"></i>\n          <div style="border: 2px dashed var(--accent-orange); border-radius: 12px; padding: 20px; font-weight: bold;">Market</div>\n        </div>\n        <p style="font-size: 1.1rem; color: var(--text-muted); line-height: 1.6;">\n          The token now enters the reconstructed circulation sequence, being used for trade and taxes.\n        </p>\n        <button class="action-btn" onclick="setStage('counterfeit')">Continue &rarr;</button>\n      </div>\n    `:"counterfeit"===currentStage?i='\n      <div class="sim-box">\n        <span class="label">Step 4</span>\n        <h3 style="font-size: 2rem; margin: 10px 0;">The Counterfeiting Problem</h3>\n        <p style="font-size: 1.1rem; color: var(--text-muted); line-height: 1.6;">\n          The experiment faced a major challenge when counterfeit tokens undermined confidence in the currency.\n        </p>\n        <div style="background: rgba(255,255,255,0.05); padding: 20px; border-radius: 8px; margin-top: 20px; text-align: left;">\n          <p style="font-weight: bold; color: var(--accent-orange);"><i class="fa-solid fa-triangle-exclamation"></i> Historical challenge</p>\n          <p style="font-size: 0.95rem; color: var(--text-muted); margin-top: 10px; line-height: 1.5;">\n            When a token\'s accepted value is much greater than the value of its material (and the minting design is easy to copy), maintaining trust and controlling counterfeiting becomes critical.\n          </p>\n        </div>\n        <button class="action-btn" onclick="setStage(\'withdrawal\')">See the Outcome &rarr;</button>\n      </div>\n    ':"withdrawal"===currentStage?i='\n      <div class="sim-box">\n        <span class="label">Step 5</span>\n        <h3 style="font-size: 2rem; margin: 10px 0;">Withdrawal</h3>\n        <p style="font-size: 1.1rem; color: var(--text-muted); line-height: 1.6;">\n          Due to rampant counterfeiting and economic chaos, the token currency experiment was eventually withdrawn, bringing the experiment to a costly end.\n        </p>\n        <button class="action-btn" onclick="setStage(\'complete\')">Complete Case Study</button>\n      </div>\n    ':"complete"===currentStage&&(i='\n      <div class="sim-box" style="border-color: var(--accent-gold);">\n        <h3 style="font-size: 2rem; margin: 10px 0; color: var(--accent-gold);">Simulation Complete</h3>\n        <p style="font-size: 1.1rem; color: var(--text-muted); line-height: 1.6; margin-bottom: 20px;">\n          You have completed the educational reconstruction. Scroll down to read the documented historical timeline.\n        </p>\n        <button class="action-btn" style="background: transparent; border: 1px solid var(--accent-gold); color: var(--accent-gold);" onclick="setStage(\'select\')"><i class="fa-solid fa-rotate-right"></i> Restart Simulation</button>\n      </div>\n    '),e.innerHTML=i}document.addEventListener("DOMContentLoaded",()=>{renderTokens(),renderTimeline(),renderSources(),renderSimulation()});